"use client"

import { Fragment } from "react"
import { kroner } from "@/fineliner/blocks/dashboard-01-parts"
import { Separator } from "@/fineliner/ui/separator"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/fineliner/ui/table"

// The dashboard's lists, usable on their own: a ledger of the records on hold, and the next sessions in the room
// grouped by day.

export interface Hold {
  /** Catalogue number, LR-0000. */
  id: string
  title: string
  artist: string
  /** Who it is held for. */
  guest: string
  /** Until when: "Thu 5 Nov". */
  until: string
  /** Price in kroner. */
  price: number
  /** A page for the record; its title links there. */
  href?: string
}

/**
 * Records on hold: what, for whom and until when, and the price. In a table narrower than 20rem (a 320px phone) the
 * guest and date move under the record, so no column is squeezed to a word a line.
 */
export function HoldsTable({ holds }: { holds: Hold[] }) {
  const until = (hold: Hold) => (
    <>
      until <span className="whitespace-nowrap">{hold.until}</span>
    </>
  )
  return (
    <div className="@container/holds">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Record</TableHead>
            <TableHead className="@max-[20rem]/holds:hidden">
              Held for
            </TableHead>
            <TableHead className="text-right">Price</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {holds.map((hold) => (
            <TableRow key={hold.id}>
              <TableCell className="whitespace-normal">
                {hold.href ? <a href={hold.href}>{hold.title}</a> : hold.title}
                <span className="block text-small leading-small text-pen-quiet">
                  {hold.artist}
                </span>
                <span className="block text-small leading-small text-pen-quiet @min-[20rem]/holds:hidden">
                  For {hold.guest},{" "}
                  <span className="whitespace-nowrap">until {hold.until}</span>
                </span>
              </TableCell>
              <TableCell className="whitespace-normal @max-[20rem]/holds:hidden">
                {hold.guest}
                <span className="block text-small leading-small text-pen-quiet">
                  {until(hold)}
                </span>
              </TableCell>
              <TableCell className="text-right font-type text-small">
                {kroner(hold.price)}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

export interface NextSession {
  id: string
  /** The day it falls on, as its group's heading: "Today", "Tuesday 3 November". */
  day: string
  /** Start, HH:MM. */
  start: string
  minutes: number
  guest: string
  party: number
}

const length = (minutes: number) =>
  minutes % 60
    ? minutes > 60
      ? `${Math.floor(minutes / 60)} h ${minutes % 60} min`
      : `${minutes} min`
    : `${minutes / 60} ${minutes === 60 ? "hour" : "hours"}`

/** The next sessions in the room, grouped under their day: start time in the typewriter, the guest, how long and how many. */
export function NextSessions({ sessions }: { sessions: NextSession[] }) {
  const days = [...new Set(sessions.map((s) => s.day))]
  if (!days.length)
    return (
      <p className="m-0 text-small leading-small text-pen-quiet">
        Nothing booked yet.
      </p>
    )
  return (
    <div className="flex flex-col gap-hair">
      {days.map((day, i) => (
        <Fragment key={day}>
          {i > 0 && <Separator className="text-pen-faint" />}
          <section aria-label={day}>
            <h3 className="label m-0 text-pen-quiet">{day}</h3>
            <ul className="m-0 mt-hair flex list-none flex-col gap-tight p-0">
              {sessions
                .filter((s) => s.day === day)
                .map((s) => (
                  <li
                    key={s.id}
                    className="grid grid-cols-[3.25rem_minmax(0,1fr)] items-baseline gap-x-tight"
                  >
                    <span className="font-type text-small">{s.start}</span>
                    <span className="min-w-0">
                      <span className="block text-ui leading-ui">
                        {s.guest}
                      </span>
                      <span className="block text-small leading-small text-pen-quiet">
                        {length(s.minutes)} · {s.party}{" "}
                        {s.party === 1 ? "guest" : "guests"}
                      </span>
                    </span>
                  </li>
                ))}
            </ul>
          </section>
        </Fragment>
      ))}
    </div>
  )
}

"use client"

import type { ReactNode } from "react"
import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/fineliner/ui/card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  drawnBar,
  type ChartConfig,
} from "@/fineliner/ui/chart"

// The dashboard's parts, usable on their own: a headline figure in the typewriter, a panel with a title and one line
// on what it shows, and the week's guests as bars drawn by the pen.

// A fixed locale, so the server and every browser print the same digits.
const count = new Intl.NumberFormat("en-GB")

/** A price in kroner: 4,320 kr. */
export const kroner = (n: number) => `${count.format(n)} kr`

/**
 * A headline figure: what it counts in the label voice, the figure in the typewriter, one line of context. In a column
 * too narrow for "4,320 kr" at heading size (a 320px phone) the figure steps down a size.
 */
export function Figure({
  label,
  value,
  note,
}: {
  label: string
  value: string
  note: string
}) {
  return (
    <div className="@container/figure min-w-0">
      <p className="label m-0 text-pen-quiet">{label}</p>
      <p className="m-0 mt-hair font-type text-lead leading-subhead tabular-nums @min-[9rem]/figure:text-h2">
        {value}
      </p>
      <p className="m-0 text-small leading-small text-pen-quiet">{note}</p>
    </div>
  )
}

/**
 * A section of the dashboard as a card: its title, one line on what it shows, then the chart, table or list. Open on
 * the page by default; framed when the page's containers are boxed.
 */
export function Panel({
  title,
  note,
  action,
  children,
  className,
}: {
  title: string
  note: string
  /** A link or button beside the title. */
  action?: ReactNode
  children: ReactNode
  className?: string
}) {
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>
          <h2 className="m-0 font-[inherit] text-[length:inherit] leading-[inherit]">
            {title}
          </h2>
        </CardTitle>
        <CardDescription>{note}</CardDescription>
        {action && <CardAction>{action}</CardAction>}
      </CardHeader>
      <CardContent>{children}</CardContent>
    </Card>
  )
}

export interface GuestDay {
  /** The axis label: "Mon 2". */
  day: string
  booked: number
  cancelled: number
}

const guestsConfig = {
  booked: { label: "Guests booked" },
  cancelled: { label: "Cancelled" },
} satisfies ChartConfig

/** Guests in the room by day: those booked in solid ink, those who cancelled in outline on top. */
export function GuestsChart({ days }: { days: GuestDay[] }) {
  return (
    <ChartContainer config={guestsConfig} className="aspect-auto h-60 w-full">
      <BarChart
        accessibilityLayer
        data={days}
        margin={{ top: 8, right: 8, bottom: 0, left: 0 }}
      >
        <CartesianGrid vertical={false} />
        <XAxis
          dataKey="day"
          tickLine={false}
          tickMargin={8}
          // Recharts measures ticks in the page's default face; the typewriter is wider, so leave it room.
          minTickGap={16}
          interval="preserveStartEnd"
        />
        <YAxis
          tickLine={false}
          axisLine={false}
          width={28}
          allowDecimals={false}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <ChartLegend content={<ChartLegendContent />} />
        <Bar dataKey="booked" stackId="day" shape={drawnBar} />
        <Bar dataKey="cancelled" stackId="day" shape={drawnBar} />
      </BarChart>
    </ChartContainer>
  )
}

"use client"

import { cn } from "@/fineliner/lib/utils"
import {
  HoldsTable,
  NextSessions,
  type Hold,
  type NextSession,
} from "@/fineliner/blocks/dashboard-01-lists"
import {
  Figure,
  GuestsChart,
  Panel,
  type GuestDay,
} from "@/fineliner/blocks/dashboard-01-parts"

// The shop's week at a glance: four figures in the typewriter, guests in the room as bars drawn by the pen, a ledger
// of the records on hold and the next sessions in the room. Pass your own data, shaped like SAMPLE; the layout
// follows the width of its container, so it works beside a sidebar as well as on a whole page.

export const meta = {
  title: "Dashboard",
  description:
    "The shop's week: four figures in the typewriter, guests by day drawn by the pen, the records on hold and the next sessions.",
}

export interface Dashboard01Data {
  /** Where and when, above the title. */
  kicker: string
  figures: { label: string; value: string; note: string }[]
  guests: { title: string; note: string; days: GuestDay[] }
  holds: { title: string; note: string; rows: Hold[] }
  sessions: { title: string; note: string; rows: NextSession[] }
}

/** Listening Room on Monday 2 November 2026: the fortnight's bookings and the records in the shop. */
export const SAMPLE: Dashboard01Data = {
  kicker: "The shop · first week of November",
  figures: [
    { label: "In the shop", value: "18", note: "3 on hold, 2 sold" },
    {
      label: "At asking price",
      value: "4,320 kr",
      note: "Records not yet sold",
    },
    {
      label: "Sessions booked",
      value: "14",
      note: "30 guests, 13 hours in the room",
    },
    {
      label: "Thursday seats",
      value: "32 of 48",
      note: "Four evenings in November",
    },
  ],
  guests: {
    title: "Guests in the room",
    note: "By day, the fortnight from Monday 2 November",
    days: [
      { day: "Mon 2", booked: 6, cancelled: 0 },
      { day: "Tue 3", booked: 3, cancelled: 0 },
      { day: "Wed 4", booked: 2, cancelled: 1 },
      { day: "Thu 5", booked: 5, cancelled: 0 },
      { day: "Fri 6", booked: 2, cancelled: 0 },
      { day: "Sat 7", booked: 5, cancelled: 0 },
      { day: "Tue 10", booked: 1, cancelled: 0 },
      { day: "Thu 12", booked: 2, cancelled: 0 },
      { day: "Sat 14", booked: 4, cancelled: 0 },
    ],
  },
  holds: {
    title: "On hold",
    note: "Records kept behind the counter",
    rows: [
      {
        id: "LR-0414",
        title: "Neon Orchard",
        artist: "Satoko Ishii",
        guest: "Maya Singh",
        until: "Thu 5 Nov",
        price: 420,
      },
      {
        id: "LR-0429",
        title: "Paper Moons",
        artist: "Odile & the Lanterns",
        guest: "Jonas Berg",
        until: "Thu 5 Nov",
        price: 180,
      },
      {
        id: "LR-0423",
        title: "Rain on Tin",
        artist: "Mabel Okafor",
        guest: "Ama Owusu",
        until: "Sat 7 Nov",
        price: 220,
      },
    ],
  },
  sessions: {
    title: "Next in the room",
    note: "The room seats four",
    // prettier-ignore
    rows: [
      { id: "S-102", day: "Today", start: "14:00", minutes: 30, guest: "Jonas Berg", party: 1 },
      { id: "S-103", day: "Today", start: "16:00", minutes: 60, guest: "Ama Owusu", party: 3 },
      { id: "S-104", day: "Tuesday 3 November", start: "12:00", minutes: 90, guest: "Lukas Brandt", party: 2 },
      { id: "S-105", day: "Tuesday 3 November", start: "15:30", minutes: 30, guest: "Ingrid Sæther", party: 1 },
      { id: "S-106", day: "Wednesday 4 November", start: "11:00", minutes: 60, guest: "Tomás Ferreira", party: 2 },
      { id: "S-108", day: "Thursday 5 November", start: "11:30", minutes: 30, guest: "Peter Lund", party: 1 },
    ],
  },
}

export interface Dashboard01Props {
  data?: Dashboard01Data
  title?: string
  className?: string
}

export function Dashboard01({
  data = SAMPLE,
  title = "Overview",
  className,
}: Dashboard01Props) {
  return (
    <div className={cn("@container", className)}>
      <div className="mx-auto max-w-[72rem] px-snug pt-section pb-page @min-[40rem]:px-line">
        <p className="label m-0 text-pen-quiet">{data.kicker}</p>
        <h1 className="m-0 mt-hair text-h1">{title}</h1>

        <section
          aria-label="Figures"
          className="mt-line grid grid-cols-2 gap-line @min-[56rem]:grid-cols-4 @min-[56rem]:gap-x-section"
        >
          {data.figures.map((figure) => (
            <Figure key={figure.label} {...figure} />
          ))}
        </section>

        <div className="mt-section grid gap-section @min-[56rem]:grid-cols-[minmax(0,1fr)_18rem] @min-[56rem]:gap-x-page">
          <Panel title={data.guests.title} note={data.guests.note}>
            <GuestsChart days={data.guests.days} />
          </Panel>
          <Panel
            title={data.sessions.title}
            note={data.sessions.note}
            className="@min-[56rem]:col-start-2 @min-[56rem]:row-span-2 @min-[56rem]:row-start-1"
          >
            <NextSessions sessions={data.sessions.rows} />
          </Panel>
          <Panel title={data.holds.title} note={data.holds.note}>
            <HoldsTable holds={data.holds.rows} />
          </Panel>
        </div>
      </div>
    </div>
  )
}

export default Dashboard01
